import {STRUCTURAL_TYPE,structuralLayout} from './structural-brain.js';
import {DUAL_BRAIN_TYPE} from './dual-brain-layout.js';
/** Проверки текущей модели. Управляемый выбор нужен только фикстурам;
 * обычные основатели используют случайные наследуемые сети. */
import {Evolution,RULES,validateGenomeFile,mutateGenome} from './evolution.js';
import {TEMPORAL_LAYOUT,GATE_OFFSET,GATE_OUTPUT_BIAS,GATE_PARAMETERS,SET_BLOCKS,SET_PARAMETER_COUNT} from './temporal-layout.js';
import {genomeMetadata,randomNeuralGenome} from './genome.js';
import {createControllerState,controllerProblems} from './brain-controller.js';
import {Random} from './simulation.js';
import {getMemory} from './cognition.js';
import {positionKey} from './navigation.js';
import {prepareSetDecisionInput} from './temporal-inputs.js';
import {setCommonForward,setCandidateForward,setGradient,expectedSetValue,evaluateSetBrain} from './temporal-brain.js';
import {cloneSetInput} from './set-brain-inputs.js';
import {checkInvariants,validateExperimentConfig} from './experiment-runner.js';
import {analyzeGenome} from './genome-analysis.js';
const assert=(v,m)=>{if(!v)throw new Error(m);},near=(a,b,m)=>assert(Math.abs(a-b)<1e-8,m+`: ${a} / ${b}`);
function fixture(count=1,options={}){
 const w=new Evolution({brainType:TEMPORAL_LAYOUT.brainType,seed:42,population:count,limit:Math.max(3,count),foodSources:0,learning:false,memory:false,...options});
 for(const c of w.tiles){c.food=0;c.maxFood=0;c.terrain='land';}
 for(const a of w.agents){w.moveAgent(a,{x:12,y:12});a.frameRotation=0;a.genome.fill(0,0,TEMPORAL_LAYOUT.genes);a.genome[GATE_OFFSET+GATE_OUTPUT_BIAS]=-1;a.brain=createControllerState(a.genome);a.wanted=8;}
 w.rebuildOccupancy();w.choose=function(a,prepared){const {frame,options}=this.evaluateFrame(a,prepared);const c=options.find(c=>c.action===(typeof a.wanted==='function'?a.wanted(a,this):a.wanted))??options.find(c=>c.action===8);a.lastDecision={tick:this.tick,options,chosen:c.action};return this.executableDecision(frame,c);};return w;
}
function run(w,n){for(let i=0;i<n&&w.agents.length;i++)w.substep();}
function age(w,a,n=100){a.bornSubtick=w.subtick-n*10;a.born=-n;a.age=n;}
function check(id,label,run){return {id:'time-'+id,label:'0.36 · '+label,run};}
export const TEMPORAL_CHECKS=[
 check('analysis','Анализ v14 показывает структуру, обе сети и регуляторы',()=>{const w=new Evolution({population:1}),r=analyzeGenome(w.genomeFile(w.agents[0]));assert(r.geneCount===w.agents[0].genome.length&&r.genomeVersion===14&&r.brainType===STRUCTURAL_TYPE,'Схема анализа');assert(r.properties.some(p=>p.key==='structuralRate')&&r.mutation&&r.properties.filter(p=>p.group==='Малый мозг').length===GATE_PARAMETERS,'Потеряны параметры анализа');}),
 check('trial-contract','Новые испытания не принимают автоматическое рождение',()=>{const config={seeds:[42],population:1,limit:3,steps:1000,parallel:1};assert(validateExperimentConfig(config).brainType===DUAL_BRAIN_TYPE,'Старый мозг испытаний');let failed=false;try{validateExperimentConfig({...config,reproduction:'automatic-86-55-v1'});}catch{failed=true;}assert(failed,'Автоматизм доступен');}),
 check('trial-invariants','Инварианты испытаний совпадают с новой моделью и восстановлением',async()=>{const {captureBenchmarkState,restoreBenchmarkState}=await import('./benchmark-state.js');const a=new Evolution({population:12,limit:24});for(let i=0;i<12;i++){a.step();checkInvariants(a);}const b=restoreBenchmarkState(captureBenchmarkState(a));for(let i=0;i<5;i++){a.step();b.step();checkInvariants(b);assert(JSON.stringify(a.snapshot())===JSON.stringify(b.snapshot()),'Восстановление процесса/буферов');}}),
 check('schema','v14: переменный основной мозг, внимание и регуляторы',()=>{const w=new Evolution({population:1}),g=w.agents[0].genome;assert(structuralLayout(g)?.hidden>=4,'Размер генома');assert(genomeMetadata(g).version===14,'Версия');assert(validateGenomeFile(w.genomeFile(w.agents[0])).length===g.length,'Импорт');assert(!('pain'in w.agents[0])&&w.tiles.every(c=>!('risk'in c)),'Удалены боль/риск');}),
 check('old-base','Старый геном не читается под новым смыслом',()=>{let failed=false;try{new Evolution({population:1,baseGenome:Array(990).fill(0)});}catch{failed=true;}assert(failed,'Старая основа принята');}),
 check('move','Движение меняет гекс только после15 подшагов',()=>{const w=fixture(),a=w.agents[0];a.wanted=a=>a.brain.position.q===0?0:8;run(w,14);assert(a.x===12&&a.brain.position.q===0,'Ранний переход');near(w.stats.actionSpent,14*.078,'Расход');run(w,1);assert(a.x===13&&a.brain.position.q===1,'Переход не завершён');assert(w.stats.completed[0]===1,'Завершение');}),
 check('wait-repeat','Ожидание5, первоначальная/повторная скидка0,03',()=>{const w=fixture();run(w,5);near(w.stats.brainSpent,.06,'Два плановых выбора');near(w.stats.actionSpent,.15,'Физический расход ожидания');assert(w.stats.completed[8]===1,'Длительность');}),
 check('deposit','Выкладывание3, перенос одной порции и расход0,108',()=>{const w=fixture(),a=w.agents[0];a.inventory=1;w.initialFood++;a.wanted=10;run(w,2);assert(a.inventory===1&&w.tile(a.x,a.y).food===0,'Раннее выкладывание');run(w,1);assert(a.inventory===0&&w.tile(a.x,a.y).food===1,'Перенос');near(w.stats.actionSpent,.108,'Цена выкладывания');}),
 check('meal','Трапеза2, усвоение новой порции со следующего интервала',()=>{const w=fixture(),a=w.agents[0];a.inventory=1;a.wanted=7;run(w,1);near(a.stomach,0,'Ранняя трапеза');run(w,1);near(a.stomach,22,'Порция');run(w,1);near(a.stomach,21.89,'Усвоение');}),
 check('gather','Сбор5 не резервирует пищу при начале',()=>{const w=fixture(),a=w.agents[0],c=w.tile(a.x,a.y);c.food=1;a.wanted=6;run(w,4);assert(c.food===1&&a.inventory===0,'Резерв/ранний результат');run(w,1);assert(c.food===0&&a.inventory===1,'Сбор');}),
 check('competition','Последняя порция достаётся одному, остальные попытки прерываются',()=>{const w=fixture(3),c=w.tile(12,12);c.food=1;for(const a of w.agents)a.wanted=6;run(w,5);assert(w.agents.reduce((n,a)=>n+a.inventory,0)===1&&c.food===0,'Порция размножилась');assert(w.stats.completed[6]===1&&w.stats.interrupted[6]===2,'Конкуренция');near(w.stats.actionSpent,3*.33,'Расход всех попыток');}),
 check('early-failure','Исчезновение пищи прекращает ещё незавершённый сбор',()=>{const w=fixture(),a=w.agents[0],c=w.tile(12,12);c.food=1;a.wanted=6;run(w,2);c.food=0;run(w,1);assert(w.stats.interrupted[6]===1&&a.process.action===8,'Сбор не прекращён');near(w.stats.actionSpent,.198,'Понесённые расходы');}),
 check('review-continue','Пересмотр сохраняет прогресс и стоит0,10',()=>{const w=fixture(),a=w.agents[0];a.wanted=0;a.brain.gateBase[GATE_OUTPUT_BIAS]=1;run(w,3);assert(a.process.elapsed===3&&w.stats.started[0]===1,'Прогресс сброшен');assert(w.stats.reviews===3,'Не каждый подшаг');near(w.stats.brainSpent,.4,'Цена четырёх выборов');}),
 check('review-cancel','Прерванный переход оставляет исходный гекс и расходы',()=>{const w=fixture(),a=w.agents[0];a.wanted=(a,w)=>w.subtick<3?0:8;a.brain.gateBase[GATE_OUTPUT_BIAS]=1;run(w,3);assert(a.x===12&&a.process.action===8&&w.stats.interrupted[0]===1,'Прерывание');near(w.stats.actionSpent,.234,'Расход движения');}),
 check('direction-repeat','Скидка движения сравнивает направление, а не номер команды',()=>{const w=fixture(),a=w.agents[0];a.wanted=a=>a.brain.position.q===0?3:0;run(w,15);near(w.stats.brainSpent,.13,'Прямое продолжение после поворота взгляда');}),
 check('soft-limit','Начатые роды завершаются сверхN',()=>{const w=fixture(2,{limit:3});for(const a of w.agents){age(w,a);a.wanted=9;}run(w,19);assert(w.agents.length===2,'Раннее рождение');run(w,1);assert(w.agents.length===4&&w.stats.births===2,'Жёсткий лимит/резерв');}),
 check('birth-lock','Роды20 без малой сети и добровольного пересмотра',()=>{const w=fixture(),a=w.agents[0];age(w,a);a.wanted=9;a.brain.gateBase[GATE_OUTPUT_BIAS]=1;run(w,19);assert(a.process.action===9&&w.stats.gateCalls===0,'Пересмотр родов');near(a.energy,67.9,'Ранний платёж');run(w,1);assert(w.stats.births===1&&a.lastBirthAge===a.age,'Завершение/интервал');near(w.stats.birthSpent,4,'Работа родов');}),
 check('birth-end','В конце родов не повторяются пороги50/40',()=>{const w=fixture(),a=w.agents[0];age(w,a);a.wanted=9;run(w,1);a.energy=40;a.health=20;run(w,19);assert(w.stats.births===1,'Повторные пороги');}),
 check('death-birth','Смерть раньше окончания родов исключает потомка',()=>{const w=fixture(),a=w.agents[0];age(w,a);a.wanted=9;run(w,1);age(w,a,RULES.maxAge-.1);run(w,1);assert(!a.alive&&w.stats.births===0&&w.agents.length===0,'Рождение после смерти');}),
 check('birth-energy','Недостаток32 в конце не создаёт ребёнка',()=>{const w=fixture(),a=w.agents[0];age(w,a);a.wanted=9;run(w,1);a.energy=31;run(w,19);assert(w.stats.births===0&&w.stats.interrupted[9]===1,'Платёж из отсутствующей энергии');}),
 check('newborn','Ребёнок начинает выбор на следующем подшаге',()=>{const w=fixture(),a=w.agents[0];age(w,a);a.wanted=9;run(w,20);const child=w.agents.find(c=>c.parentId===a.id);assert(child&&child.process===null,'Ранний выбор ребёнка');run(w,1);assert(child.process&&child.brain.pending===null,'Нет первого действия при отключённой памяти/обучении');}),
 check('hunger','Нехватка энергии мышления/действия оплачивается здоровьем без второго штрафа',()=>{const w=fixture(),a=w.agents[0];a.energy=0;a.brain.gateBase[GATE_OUTPUT_BIAS]=1;run(w,1);near(a.health,100-(.03+.03+.10)*25/6,'Дефицит/двойной урон');near(w.stats.brainSpent,0,'Отрицательная энергия');}),
 check('partial-fee','За решение списывается только доступный остаток',()=>{const w=fixture(),a=w.agents[0];a.energy=.02;run(w,1);near(a.energy,0,'Остаток');near(w.stats.brainSpent,.02,'Цена решения');}),
 check('memory-time','Частые наблюдения не умножают статистику памяти',()=>{const w=fixture(1,{memory:true}),a=w.agents[0];run(w,10);const r=getMemory(a.brain,positionKey(a.brain.position));near(r.samples,1,'Наблюдения за1Т');near(r.visits,1,'Пребывание за1Т');assert(!('injuries'in r),'Остался риск памяти');}),
 check('learning','Обучение живого по следующему выбору',()=>{const w=fixture(1,{learning:true}),a=w.agents[0];run(w,4);assert(a.brain.updates===0,'Промежуточное обучение');run(w,1);assert(a.brain.updates===1&&Number.isFinite(a.brain.lastLearning.reward),'Нет обучения');}),
 check('death-learning','Умерший не получает финальное обучение',()=>{const w=fixture(1,{learning:true}),a=w.agents[0];a.energy=0;a.health=.1;run(w,1);assert(!a.alive&&a.brain.updates===0,'Бесполезное финальное обучение');}),
 check('gate-inherited','Малая сеть наследуется, личные поправки/память нет',()=>{const w=fixture(1,{learning:true,memory:true,mutations:false}),a=w.agents[0];age(w,a);a.wanted=9;run(w,20);const c=w.agents.find(x=>x.parentId===a.id);assert(c&&c.genome.every((v,i)=>v===a.genome[i]),'Геном');assert(c.brain.gateBase.every((v,i)=>v===a.brain.gateBase[i]),'Малый мозг');assert(c.brain.networkDelta.every(x=>x===0)&&c.brain.memory.size===0,'Личный опыт наследуется');}),
 check('gate-mutations','Параметры малой сети мутируют как обычные веса',()=>{const g=randomNeuralGenome(new Random(17),TEMPORAL_LAYOUT.brainType),c=mutateGenome(g,new Random(22),1,.7);assert(c.slice(GATE_OFFSET).some((x,i)=>x!==g[GATE_OFFSET+i]),'Нет мутации малой сети');assert(g!==c&&c.every(x=>Math.abs(x)<=8),'Границы');}),
 check('scalar','Числовой TD и полный оценщик дают одну ожидаемую оценку',()=>{const w=new Evolution({population:1}),a=w.agents[0],request=w.decisionFrame(a).request,input=prepareSetDecisionInput(a.brain,request),all=evaluateSetBrain(a.brain,request,true,input),expected=all.reduce((n,c)=>n+c.probability*c.learningValue,0);near(expected,expectedSetValue(a.brain,request,input),'Ожидаемая оценка');}),
 check('gradient','Эталон v13: градиент всех1827 весов',()=>{const w=new Evolution({population:1,brainType:TEMPORAL_LAYOUT.brainType}),a=w.agents[0],r=w.decisionFrame(a).request,input=prepareSetDecisionInput(a.brain,r),frame=cloneSetInput({...input.prepared,candidate:input.rows[0].input}),p=a.brain.networkBase.slice(),g=setGradient(p,frame).gradient,epsilon=1e-6;for(let i=0;i<SET_PARAMETER_COUNT;i++){const v=p[i];p[i]=v+epsilon;const hi=setCandidateForward(p,setCommonForward(p,frame),frame.candidate).value;p[i]=v-epsilon;const lo=setCandidateForward(p,setCommonForward(p,frame),frame.candidate).value;p[i]=v;assert(Math.abs((hi-lo)/(2*epsilon)-g[i])<1e-5,'Градиент '+i);}}),
 check('reward-time','Разбиение одинакового времени сохраняет подкрепление',()=>{const g=.9,q=g**.1,b=.04*(1-q)/(1-g),f=.5,reward=n=>b*f*(1-q**n)/(1-q)+(q**n-1)*f;near(reward(10),reward(5)+q**5*reward(5),'Разбиение');near(b*f*(1-q**10)/(1-q),.04*f,'Масштаб ощущения');}),
 check('balances','Миры разныхseed сохраняют балансы/конечные веса',()=>{for(const seed of [17,42,98]){const w=new Evolution({seed,population:12,limit:24});for(let i=0;i<25;i++){w.step();const b=w.balances();assert(b.foodError===0&&Math.abs(b.energyError)<1e-6,'Баланс');for(const a of w.agents)assert(controllerProblems(a.brain).length===0,controllerProblems(a.brain).join(';'));}}}),
 check('repeatability','Повторный мир сохраняет действия и RNG',()=>{const a=new Evolution({population:8}),b=new Evolution({population:8});for(let i=0;i<15;i++){a.step();b.step();assert(JSON.stringify(a.snapshot())===JSON.stringify(b.snapshot()),'Повторяемость');}}),
];
